def book_reservation(user_id: str, origin: str, destination: str, flight_type: str, cabin: str, flights: list, passengers: list, payment_methods: list, total_baggages: int, nonfree_baggages: int, insurance: str):
    """
    Book a flight reservation and charge the given payment method(s).

    This tool NORMALIZES sloppy arguments and completes the payment for you, so
    prefer calling it directly instead of re-checking the math yourself:
      - Each flight object only needs {"flight_number": ..., "date": ...}; any
        extra keys (origin, destination, price, cabin) are ignored.
      - Each passenger object needs {"first_name", "last_name", "dob"} where dob
        is 'YYYY-MM-DD'. If you omit a passenger's dob but that person is the
        account holder or a saved passenger on the profile, their dob is filled in
        automatically.
      - Each payment object is {"payment_id": ..., "amount": ...}. If the amounts
        you pass do not add up to the exact total price, and exactly one payment
        method is used, the amount is corrected automatically; if a credit card is
        among several methods, the leftover is put on the credit card.

    Args:
        user_id: The ID of the user booking, such as 'sara_doe_496'.
        origin: The IATA code for the origin city, such as 'SFO'.
        destination: The IATA code for the final destination city, such as 'JFK'. For a round_trip this is the far city, NOT the origin.
        flight_type: 'one_way' or 'round_trip'.
        cabin: 'basic_economy', 'economy', or 'business'. Must be the same for every flight.
        flights: A list of flight objects, each {"flight_number": "HAT271", "date": "2024-05-26"}. Include every leg in order.
        passengers: A list of passenger objects, each {"first_name": "Sophia", "last_name": "Silva", "dob": "1957-10-05"}.
        payment_methods: A list of payment objects, each {"payment_id": "certificate_8045380", "amount": 348}. At most one certificate, one credit card, and three gift cards.
        total_baggages: Total number of checked bags across all passengers.
        nonfree_baggages: Number of checked bags beyond the free allowance (these cost $50 each).
        insurance: 'yes' or 'no'.
    """
    import re

    def _as_dict(x):
        if isinstance(x, dict):
            return x
        if hasattr(x, "model_dump"):
            try:
                return x.model_dump()
            except Exception:
                return None
        if isinstance(x, str):
            try:
                import json as _json
                v = _json.loads(x)
                return v if isinstance(v, dict) else None
            except Exception:
                return None
        return None

    def _norm_flights(fl):
        out = []
        for f in fl:
            if isinstance(f, dict):
                fn = f.get("flight_number") or f.get("flightNumber") or f.get("number")
                dt = f.get("date")
                if fn is not None and dt is not None:
                    out.append({"flight_number": fn, "date": dt})
                else:
                    out.append(f)
            else:
                out.append(f)
        return out

    def _norm_passengers(ps, name_dob):
        out = []
        for p in ps:
            if not isinstance(p, dict):
                out.append(p)
                continue
            q = dict(p)
            if not q.get("dob"):
                for alt in ("date_of_birth", "dateOfBirth", "birth_date", "birthday"):
                    if q.get(alt):
                        q["dob"] = q[alt]
                        break
            fn = str(q.get("first_name", "")).strip().lower()
            ln = str(q.get("last_name", "")).strip().lower()
            if not q.get("dob"):
                q["dob"] = name_dob.get((fn, ln)) or name_dob.get((fn, "")) or q.get("dob")
            out.append({
                "first_name": q.get("first_name"),
                "last_name": q.get("last_name"),
                "dob": q.get("dob"),
            })
        return out

    def _norm_payments(pm):
        out = []
        for m in pm:
            if isinstance(m, str):
                out.append({"payment_id": m})
                continue
            if not isinstance(m, dict):
                out.append(m)
                continue
            pid = m.get("payment_id")
            if not pid:
                src = m.get("source") or m.get("type")
                rid = m.get("id")
                if rid and src and not str(rid).startswith(str(src)):
                    pid = "{}_{}".format(src, rid)
                elif rid:
                    pid = rid
            d = {"payment_id": pid}
            if m.get("amount") is not None:
                d["amount"] = m.get("amount")
            out.append(d)
        return out

    # Build a name -> dob map from the user's profile so we can backfill any
    # missing passenger dob (account holder + saved passengers).
    name_dob = {}
    ud = _as_dict(env_get_user_details(user_id=user_id))
    if ud:
        nm = ud.get("name") or {}
        if ud.get("dob") and nm:
            name_dob[(str(nm.get("first_name", "")).strip().lower(),
                      str(nm.get("last_name", "")).strip().lower())] = ud["dob"]
        for sp in (ud.get("saved_passengers") or []):
            sp = _as_dict(sp) or sp
            if isinstance(sp, dict) and sp.get("dob"):
                name_dob[(str(sp.get("first_name", "")).strip().lower(),
                          str(sp.get("last_name", "")).strip().lower())] = sp["dob"]

    nflights = _norm_flights(flights)
    npass = _norm_passengers(passengers, name_dob)
    npay = _norm_payments(payment_methods)

    result = env_book_reservation(
        user_id=user_id, origin=origin, destination=destination,
        flight_type=flight_type, cabin=cabin, flights=nflights,
        passengers=npass, payment_methods=npay,
        total_baggages=total_baggages, nonfree_baggages=nonfree_baggages,
        insurance=insurance,
    )

    # Auto-reconcile a payment total that does not add up (fires ONLY on that
    # specific error string, so a correct call is never re-run).
    if isinstance(result, str) and "does not add up" in result:
        mm = re.search(r"total price is (\d+), but paid (\d+)", result)
        if mm:
            total = int(mm.group(1))
            paid = int(mm.group(2))
            delta = total - paid
            fixed = [dict(x) if isinstance(x, dict) else x for x in npay]
            valid = [x for x in fixed if isinstance(x, dict)]
            cc = [x for x in valid if str(x.get("payment_id", "")).startswith("credit_card")]
            if len(valid) == 1:
                valid[0]["amount"] = total
                return env_book_reservation(
                    user_id=user_id, origin=origin, destination=destination,
                    flight_type=flight_type, cabin=cabin, flights=nflights,
                    passengers=npass, payment_methods=fixed,
                    total_baggages=total_baggages, nonfree_baggages=nonfree_baggages,
                    insurance=insurance,
                )
            elif cc:
                cc[0]["amount"] = int(cc[0].get("amount", 0)) + delta
                return env_book_reservation(
                    user_id=user_id, origin=origin, destination=destination,
                    flight_type=flight_type, cabin=cabin, flights=nflights,
                    passengers=npass, payment_methods=fixed,
                    total_baggages=total_baggages, nonfree_baggages=nonfree_baggages,
                    insurance=insurance,
                )
    return result
